    let pagesize = pagesize.min(10000);
    let Some(_) = session else {
        return Ok(ApiResult::auth_error().into());
    };
    // 개수는 페이지 / 정렬 없이 같은 조건으로 센다.
    let count_args = args.clone();
    let paged = page != 0 && pagesize != 0;
    if paged {
        args.push(Arg::Paging { page, pagesize });
    }
    // orderby 는 이 테이블 컬럼 + asc/desc 만 남긴다 (모르는 항목은 버린다). 없으면 페이지일 때 u_id desc.
    let orderby = User::parse_order(q.get("orderby"));
    if !orderby.is_empty() {
        args.push(Arg::Ordering(orderby));
    }
    let items = User::find(&pool, &args).await?;
    let mut result = ApiResult::ok().set("items", &items);
    if paged {
        result.insert("total", User::count(&pool, &count_args).await?);
    }
